javascript:
function numVal(id) {
  const el = document.getElementById(id);
  if (!el) return 0;
  const n = parseInt(el.value, 10);
  return isNaN(n) ? 0 : n;
}

function calculateTotal() {
  const hundredValue = numVal("hundred") * 100;
  const fiftyValue = numVal("fifty") * 50;
  const twentyValue = numVal("twenty") * 20;
  const tenValue = numVal("ten") * 10;
  const fiveValue = numVal("five") * 5;

  const Twoonie = numVal("Twoonies") * 2;
  const Loonie = numVal("Loonies");
  const quartersValue = numVal("Quarters") * 0.25;
  const Dimes = numVal("Dimes") * 0.10;
  const nickelsValue = numVal("Nickels") * 0.05;

  const totalAmount =
    hundredValue + fiftyValue + twentyValue + tenValue + fiveValue +
    Twoonie + Loonie + quartersValue + Dimes + nickelsValue;

  const out = document.getElementById("totalAmount");
  if (out) out.textContent = totalAmount.toFixed(2);
}

const coinNames = {
  Twoonies: "Twoonies",
  Loonies: "Loonies",
  Quarters: "Quarters",
  Dimes: "Dimes",
  Nickels: "Nickels"
};

const lowCoins = [];

function checkCoinValue() {
  for (const coinId in coinNames) {
    const coinValue = numVal(coinId);
    const coinName = coinNames[coinId];
    if (coinValue <= 9) {
      if (!lowCoins.includes(coinName)) lowCoins.push(coinName);
    } else {
      const index = lowCoins.indexOf(coinName);
      if (index !== -1) lowCoins.splice(index, 1);
    }
  }
  const messageSpan = document.getElementById("CoinsMessage");
  if (!messageSpan) return;
  if (lowCoins.length > 0) {
    messageSpan.textContent = "Please request more " + lowCoins.join(", ") + ".";
  } else {
    messageSpan.textContent = "";
  }
}

function copyToClipboard() {
  const copiedValue = document.getElementById("totalAmount").textContent;
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(copiedValue).then(function () {
      alert("Total of $" + copiedValue + " copied to clipboard!");
    }).catch(function () {
      legacyCopy(copiedValue);
    });
  } else {
    legacyCopy(copiedValue);
  }
}

function legacyCopy(copiedValue) {
  const el = document.createElement("textarea");
  el.value = copiedValue;
  document.body.appendChild(el);
  el.select();
  document.execCommand("copy");
  document.body.removeChild(el);
  alert("Total of $" + copiedValue + " copied to clipboard!");
}

function resetCashierForm() {
  ["hundred","fifty","twenty","ten","five","Twoonies","Loonies","Quarters","Dimes","Nickels"].forEach(function (id) {
    const el = document.getElementById(id);
    if (el) el.value = "0";
  });
  lowCoins.length = 0;
  const msg = document.getElementById("CoinsMessage");
  if (msg) msg.textContent = "";
  calculateTotal();
}

frappe.ready(function () {
  calculateTotal();
});

css:
.page-content-wrapper .main-column,
.web-page-content,
.page_content {
  max-width: 100% !important;
  width: 100% !important;
  padding-left: 12px !important;
  padding-right: 12px !important;
}

.sg-page, .cc-page {
  font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 13px;
  color: #36414c;
  line-height: 1.45;
  padding: 8px 0 40px;
  max-width: 920px;
  margin: 0 auto;
  box-sizing: border-box;
}

.sg-gate {
  max-width: 420px;
  margin: 48px auto;
  text-align: center;
  font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}
.sg-gate h2 { color: #2c3338; font-size: 18px; font-weight: 600; margin: 0 0 8px; }
.sg-gate p { color: #6c7680; margin: 0 0 16px; }

.sg-btn, .cc-btn {
  display: inline-block;
  background: #2490ef;
  color: #fff !important;
  text-decoration: none;
  border: none;
  border-radius: 6px;
  padding: 8px 16px;
  font-weight: 600;
  font-size: 13px;
  cursor: pointer;
}
.sg-btn:hover, .cc-btn:hover { background: #1a7fd1; }

.cc-btn-secondary {
  display: inline-block;
  background: #fff;
  color: #36414c !important;
  border: 1px solid #d1d8dd;
  border-radius: 6px;
  padding: 8px 16px;
  font-weight: 600;
  font-size: 13px;
  cursor: pointer;
}
.cc-btn-secondary:hover { background: #f5f7fa; }

.sg-toolbar {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  margin: 0 0 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid #d1d8dd;
}
.sg-toolbar h2 {
  margin: 0;
  font-size: 18px;
  font-weight: 600;
  color: #2c3338;
}
.sg-sub { color: #6c7680; font-size: 12px; margin-top: 2px; }

.cc-total-pill {
  font-size: 13px;
  font-weight: 600;
  color: #2490ef;
  background: #eaf4fe;
  border-radius: 999px;
  padding: 8px 14px;
  align-self: center;
  font-variant-numeric: tabular-nums;
}
.cc-total-pill strong { color: #2c3338; font-size: 16px; margin-left: 4px; }

.sg-section { margin: 0 0 28px; }

.cc-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin: 0 0 14px;
}

.cc-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}
@media (max-width: 720px) {
  .cc-grid { grid-template-columns: 1fr; }
}

.sg-table-wrap {
  overflow-x: auto;
  border: 1px solid #d1d8dd;
  border-radius: 8px;
  background: #fff;
}
.sg-table {
  width: 100%;
  border-collapse: collapse;
  margin: 0;
}
.sg-table th {
  background: #f5f7fa;
  color: #2c3338;
  font-weight: 600;
  font-size: 12px;
  text-align: left;
  padding: 10px 12px;
  border-bottom: 1px solid #d1d8dd;
}
.sg-table td {
  padding: 8px 12px;
  border-bottom: 1px solid #eef0f2;
  vertical-align: middle;
}
.sg-table tr:last-child td { border-bottom: none; }

.cc-label {
  font-weight: 600;
  color: #2c3338;
  width: 55%;
}
.cc-input {
  width: 88px;
  max-width: 100%;
  height: 34px;
  border: 1px solid #d1d8dd;
  border-radius: 6px;
  padding: 4px 8px;
  font-size: 13px;
  font-variant-numeric: tabular-nums;
  color: #36414c;
  background: #fff;
}
.cc-input:focus {
  outline: none;
  border-color: #2490ef;
  box-shadow: 0 0 0 2px rgba(36, 144, 239, 0.15);
}

.cc-coin-message {
  margin-top: 12px;
  color: #e24c4c;
  font-size: 12px;
  font-weight: 600;
  min-height: 1.2em;
}
